WITH exploded AS (SELECT id, host, latency_ms, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, attr_value), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY host ORDER BY latency_ms, id, key) AS dedup_rank FROM exploded) ranked WHERE dedup_rank = 1), with_windows AS (SELECT id, host, latency_ms, key, attr_value, dedup_rank, LEAD(latency_ms) OVER (PARTITION BY host, key ORDER BY latency_ms, id, key) AS next_latency_ms, LAG(latency_ms) OVER (PARTITION BY host, key ORDER BY latency_ms, id, key) AS prev_latency_ms, ROW_NUMBER() OVER (PARTITION BY host, key ORDER BY latency_ms, id, key) AS row_seq, SUM(latency_ms) OVER (PARTITION BY key ORDER BY latency_ms, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_latency_ms FROM latest), scored AS (SELECT *, SUM(prev_latency_ms) OVER (ORDER BY row_seq, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_prev_latency_ms, AVG(cumulative_latency_ms) OVER (PARTITION BY host ORDER BY dedup_rank, id, key ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS cumulative_latency_ms_avg_6, MIN(latency_ms) OVER (PARTITION BY key) AS key_min_latency_ms FROM with_windows WHERE prev_latency_ms = 1446) SELECT * FROM (SELECT host, key, key_min_latency_ms FROM scored) src PIVOT (SUM(key_min_latency_ms) FOR key IN ('trace', 'region'));
